const rpg=(...names)=>names.map(name=>`audio/kenney-rpg/${name}.ogg`);
const paper=(...names)=>names.map(name=>`audio/freesound/${name}.wav`);
const wood=(weight,...numbers)=>numbers.map(number=>`audio/kenney-impact/impactWood_${weight}_${String(number).padStart(3,'0')}.ogg`);
function mix(clips,{gain=1,rate=[.96,1.04],interval=100,peak=-7,rms=-28}={}){
  // Match perceived weight conservatively, with headroom for the master gain
  // and small variation. Never amplify quiet backgrounds by more than 4x.
  const clipGains=Object.fromEntries(clips.map(path=>{
    const [sourcePeak,sourceRms]=levels[path];
    return [path,Math.min(4,10**((peak-sourcePeak)/20),10**((rms-sourceRms)/20))];
  }));
  return Object.freeze({clips:Object.freeze(clips),gain,rate:Object.freeze(rate),interval,clipGains:Object.freeze(clipGains)});
}
